            const _meadowPatch = _T.mx_noise_float
                ? _T
                      .mx_noise_float(_T.vec3(wp.x.mul(0.13), wp.z.mul(0.13), _T.float(7.0)))
                      .mul(_T.float(0.5))
                      .add(_T.float(0.5))
                : _T.float(0.6);
