            const _meadowW = _green
                .mul(_flat.mul(_T.float(1.0).sub(_rockW)))
                .mul(_meadowPatch.mul(_T.float(0.5)).add(_T.float(0.5)))
                .clamp(0.0, 1.0);
            // V18.346 — der Meadow-Grund liest dieselben Gras-Farben wie das Nah-Gras (Gesetz #0) → Boden + Gras
